/* @lc app=leetcode id=1882 lang=kotlin */ class Solution { fun assignTasks(servers: IntArray, tasks: IntArray): IntArray = java.util.PriorityQueue<IntArray>(compareBy<IntArray>({ it[0] }, { it[1] })).also { f -> servers.forEachIndexed { i, w -> f.add(intArrayOf(w, i)) } }.let { free -> java.util.PriorityQueue<LongArray>(compareBy<LongArray>({ it[0] }, { it[1] }, { it[2] })).let { busy -> IntArray(tasks.size).also { ans -> tasks.indices.fold(0L) { t0, j -> maxOf(t0, j.toLong()).let { t1 -> (if (free.isEmpty()) maxOf(t1, busy.peek()[0]) else t1).also { t -> generateSequence { busy.peek()?.takeIf { it[0] <= t } }.forEach { b -> busy.poll().let { free.add(intArrayOf(b[1].toInt(), b[2].toInt())) } }.let { free.poll().let { s -> busy.add(longArrayOf(t + tasks[j], s[0].toLong(), s[1].toLong())).also { ans[j] = s[1] } } } } } } } } } }